 for index in 0..262144{if let Some(prepared)=publication.preparation.as_ref().and_then(|owner|owner.prepared()){assert!(prepared.foreign_step_presence().is_some(),"the outer preparation must seal its semantic readiness before exposure");}let reached=publication.stage.as_ref().is_some_and(|stage|match cut{Some("message")=>stage.message_owner.is_some(),Some("seeds")=>stage.seed_owner.is_some(),Some("metadata")=>stage.commit_metadata.is_some(),Some("publish")=>stage.commit_metadata.as_ref().is_some_and(|metadata|metadata.phase==11),_=>false});if reached{break}let selected=if publication.source_census_finished&&publication.preparation.is_none()&&publication.stage.is_none(){RetainedCloneGrant{maximum_copy_bytes:source_copy.max(publication_turn.maximum_copy_bytes),..publication_turn}}else{publication_turn};let step=turn(&mut caller,&mut decoder,selected,|cx|{let grant=cx.retained_grant();let result=cx.with_native_receiving(|native|store.advance_apply_batch(publication,4096,ArtifactStoreOneItemGrant::from_retained(grant),native));let step=result.unwrap_or_else(|error|panic!("original Store publication failed: {error:?}"));let p=match &step{ArtifactStoreOneItemAdvance::Published(_,p)|ArtifactStoreOneItemAdvance::PreparationProgress(_,p)=>*p,_=>Default::default()};if let Some(issued)=cx.receiving_issued_grant(){cx.consume_receiving_retained(issued,p)?;}else{cx.consume_retained(p)?;}cx.consume_fuel(p.copied_items as u64);Ok(step)});if matches!(step,ArtifactStoreOneItemAdvance::Published(..)){published=true;break}assert_eq!(store.generation(),before);assert_eq!(store.snapshot().unwrap().zoom,law["input"]["zoom"].as_f64().unwrap());assert!(store.original_outbound_message().is_none());assert!(index<262143,"original Store publication stalled at {:?}",publication.phase);}
