 for cut in [0,1,3,32,128,usize::MAX]{let mut owner=None;let d=RetirementDemand{copy_bytes:2*size_of::<Source>(),depth:1,..Default::default()};assert!(d.copy_bytes<=32768);let birth=RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.max(TURN.maximum_copy_bytes),..TURN};turn(caller,decoder,birth,|cx|{admit_original_construction(cx,&mut owner,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:0,release_bytes:0,depth:1},|_|Ok((Source::new(store::os_spr::DOCUMENT_BACKBONE_BATCH_MAXIMUM_BYTES,16*1024*1024)?,RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})))?;Ok(())});let source=owner.as_mut().unwrap();for index in 0..262144{if source.ready()||index==cut{break}turn(caller,decoder,TURN,|cx|{let d=source.demands(4096)?;let grant=cx.retained_grant();let mut output=None;admit_original_construction(cx,&mut output,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|Ok(((),source.advance(envelopes,7,grant)?)))?;Ok(())});assert!(index<262143);}if cut==usize::MAX{assert!(source.ready());let mut pages=None;turn(caller,decoder,TURN,|cx|{let d=Source::take_demands();let grant=cx.retained_grant();admit_original_construction(cx,&mut pages,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{let Some((pages,p))=source.take(grant)?else{panic!("native message handoff lost its actual quote")};Ok((pages,p))})?;Ok(())});let pages=pages.unwrap();let mut actual=vec![0;pages.byte_len()];assert_eq!(pages.read_bytes(0,&mut actual),actual.len());assert_eq!(actual,expected);close_typed(pages,caller,decoder);}for _ in 0..262144{if source.terminal_is_empty(){break}turn(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|{let d=source.close_demands()?;close_original_retained_step(cx,d,|grant|source.close_step(grant))?;Ok(())}));}assert!(source.terminal_is_empty());turn(caller,decoder,birth,|cx|cx.with_original_retirement(|cx|{let d=RetirementDemand{copy_bytes:size_of::<Option<Source>>(),depth:1,..Default::default()};close_original_retained_step(cx,d,|_|{drop(owner.take());Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;Ok(())}));}
